function language(){updateExperienceLanguage();document.documentElement.lang=lang;document.querySelectorAll('[data-i]').forEach(el=>el.textContent=t(el.dataset.i));document.querySelectorAll('[data-i-title]').forEach(el=>el.title=t(el.dataset.iTitle));$('language').textContent=lang==='de'?'EN':'DE';$('language').setAttribute('aria-label',lang==='de'?'Switch to English':'Auf Deutsch wechseln');$('about-content').innerHTML=aboutContent();status(statusKey);for(const [id,k]of [['swap','swap'],['pick-origin','pickOrigin'],['pick-destination','pickDestination'],['locate','locate'],['fit','fit'],['close-about','close']]){const element=$(id);if(element){element.setAttribute('aria-label',t(k));element.title=t(k);}}document.querySelectorAll('[data-profile],[data-slope]').forEach(button=>button.title=button.querySelector('[data-i]').textContent);$('origin').setAttribute('aria-label',t('from'));$('destination').setAttribute('aria-label',t('to'));if($('mobility-profile'))$('profile-description').textContent=profileDescriptions[lang][$('mobility-profile').value]||'';updateStep4Language();if(result)showResult();updateClock();renderWeather(true);}
