function renderThemeLegend(){const box=$('theme-legend'),definition=THEME_DEFS[activeTheme];if(!box||!definition||!exploreMode){if(box)box.hidden=true;return;}box.hidden=false;box.innerHTML=`<strong></strong><div class="legend-items"></div><div class="legend-zoom" hidden></div>`;box.querySelector('strong').textContent=definition[lang];const items=box.querySelector('.legend-items');for(const [color,deLabel,enLabel=deLabel] of definition.legend){const item=document.createElement('span');item.className='legend-item';item.innerHTML='<i class="legend-line"></i><span></span>';item.querySelector('i').style.background=color;item.querySelector('span').textContent=lang==='de'?deLabel:enLabel;items.append(item);}const note=box.querySelector('.legend-zoom');note.textContent=t('layersZoom');note.hidden=!map||map.getZoom()>=14.5;}
function applyTheme({reload=true}={}){
 if(map?.getLayer('network-line')){const definition=THEME_DEFS[activeTheme]||THEME_DEFS.slope;map.setPaintProperty('network-line','line-color',['case',['>', ['get','st'],0],'#aeb8bd',definition.expression]);map.setPaintProperty('network-line','line-width',['interpolate',['linear'],['zoom'],14.5,2,17,3.2,19,4.5]);map.setPaintProperty('network-line','line-opacity',.92);map.setLayoutProperty('network-line','visibility',exploreMode?'visible':'none');for(const id of ['stairs-halo','stairs-treads','slope-arrows'])if(map.getLayer(id))map.setLayoutProperty(id,'visibility',exploreMode&&activeTheme==='slope'?'visible':'none');}
 renderThemeLegend();if(reload&&exploreMode&&ready)loadVisibleCityTiles().catch(console.warn);
}

function updateCrossingLegend(){const box=$('crossing-legend');if(!box)return;box.hidden=!exploreMode||!selectedPois.has(1);if(box.hidden)return;box.replaceChildren();const heading=document.createElement('strong');heading.textContent=lang==='de'?'Ampelqualität im Fußgängeratlas':'Signal-crossing quality in the pedestrian atlas';box.append(heading);for(const quality of [3,2,1,0]){const definition=CROSSING_CLASSES[quality],item=document.createElement('div'),dot=document.createElement('i'),text=document.createElement('span');item.className='crossing-legend-item';dot.style.background=definition.color;text.textContent=`${definition[lang]} · ${definition[lang+'Rule']}`;item.append(dot,text);box.append(item);}const note=document.createElement('small');note.textContent=lang==='de'?'Farbe: Ton, Vibration und taktiles Leitsystem. Rollstuhleignung steht separat im Detailfenster.':'Colour: sound, vibration and tactile paving. Wheelchair suitability is shown separately in the detail popup.';box.append(note);}
